#!/usr/bin/env python3
# -*- coding: utf-8 -*-
r"""
iMouse 2.0 — 1-Click Local Checkout Setup & Launcher (`setup_imouse_farm.py`)

Automatically performs all setup steps inside:
  C:\Users\joey_\Desktop\Claude Code\iMouseXP-2.0-combined-candidate

What this script does when you run it on your Windows PC:
  1. Installs `tools\imouse_social_automation.py` (UTF-8, SHA-256 verified)
  2. Installs `tools\imouse_farm_server.py` (UTF-8, SHA-256 verified)
  3. Installs `tools\imouse_farm_command_center.html` (UTF-8, SHA-256 verified)
  4. Installs `src\iMouse.Console\FarmAutomationWindow.cs` (UTF-8, SHA-256 verified)
  5. Creates `Open Marketing Farm.ps1` in your candidate checkout for 1-click launch
  6. Runs `python -B tools\imouse_social_automation.py --self-check`
  7. Runs `python -B tools\imouse_farm_server.py --self-check`
  8. Boots the live `http://localhost:9914` server and opens it in your browser!
"""

from __future__ import annotations

import argparse
import base64
import hashlib
from pathlib import Path
import subprocess
import sys
import zlib

DEFAULT_CHECKOUT_DIR = r"C:\Users\joey_\Desktop\Claude Code\iMouseXP-2.0-combined-candidate"

BUNDLED_FILES = {
  "tools/imouse_social_automation.py": {
    "sha256": "bb065366e1626bdefcc3758fdc71c856e1e18e9aa367c855b45beef4f8da1fd8",
    "size": 160345,
    "zlib_b64": ""
  },
  "tools/imouse_farm_server.py": {
    "sha256": "803f05b4394acf6d3f8b974ee4821b98ef3420465eacbbd22a868f900bff8f6e",
    "size": 77803,
    "zlib_b64": ""
  },
  "tools/imouse_farm_command_center.html": {
    "sha256": "89564fa662ff3c737634bef9ef55b94be1d7ddac31845d9be27bd52c52a20d0b",
    "size": 52118,
    "zlib_b64": ""
  },
  "src/iMouse.Console/FarmAutomationWindow.cs": {
    "sha256": "b1fa004febf0cca6c6817a18b10d0045854f65da4c43961f6b22e0b0bc0430d0",
    "size": 20861,
    "zlib_b64": ""
  },
  "docs/imouse_social_automation_blueprint.md": {
    "sha256": "7943882571956732196badac87e28ec26bd88bf766b559177bb6b858c4750bc8",
    "size": 8454,
    "zlib_b64": ""
  }
}

POWERSHELL_LAUNCHER = r"""# Open Marketing Farm.ps1
# Starts the iMouse 2.0 7-Layer Marketing Farm Command Center on http://localhost:9914
$ErrorActionPreference = "Stop"
$scriptDir = Split-Path -Parent $MyInvocation.MyCommand.Path
python (Join-Path $scriptDir "tools\imouse_farm_server.py")
"""


def install_and_verify(target_root: Path, run_server: bool = True) -> int:
    print("=" * 74)
    print(f"  iMouse 2.0 Marketing Farm Automated Setup")
    print(f"  Target Checkout: {target_root}")
    print("=" * 74)

    if not target_root.exists():
        print(f"[INFO] Creating target directory: {target_root}")
        target_root.mkdir(parents=True, exist_ok=True)

    # 1. Extract and verify all bundled files
    for rel_path, meta in BUNDLED_FILES.items():
        dest = target_root / Path(rel_path)
        dest.parent.mkdir(parents=True, exist_ok=True)
        raw_bytes = zlib.decompress(base64.b64decode(meta["zlib_b64"]))
        actual_sha = hashlib.sha256(raw_bytes).hexdigest()
        if actual_sha != meta["sha256"]:
            raise RuntimeError(f"Checksum mismatch for {rel_path}: expected {meta['sha256']}, got {actual_sha}")
        dest.write_bytes(raw_bytes)
        print(f"  [OK] Installed {dest} ({len(raw_bytes)} bytes, sha256={actual_sha[:12]})")

    # 2. Write 1-click PowerShell launcher in candidate root
    ps1_path = target_root / "Open Marketing Farm.ps1"
    ps1_path.write_text(POWERSHELL_LAUNCHER, encoding="utf-8")
    print(f"  [OK] Created 1-click launcher: {ps1_path}")

    # 3. Run offline self-checks on both Python modules
    auto_py = target_root / "tools" / "imouse_social_automation.py"
    srv_py = target_root / "tools" / "imouse_farm_server.py"

    print("\nRunning offline verification suites...")
    subprocess.run([sys.executable, "-B", str(auto_py), "--self-check"], check=True, cwd=str(target_root))
    subprocess.run([sys.executable, "-B", str(srv_py), "--self-check"], check=True, cwd=str(target_root))
    print("  [OK] Both offline self-check suites passed!")

    if not run_server:
        print("\nSetup complete (--no-server specified; skipping localhost:9914 boot).")
        return 0

    print("\nBooting live Marketing Farm Command Center at http://localhost:9914 ...")
    return subprocess.call([sys.executable, str(srv_py)], cwd=str(target_root))


def main() -> int:
    ap = argparse.ArgumentParser(description="1-Click Installer & Launcher for iMouse 2.0 Marketing Farm")
    ap.add_argument("--target-dir", default=DEFAULT_CHECKOUT_DIR, help="Path to iMouseXP-2.0-combined-candidate")
    ap.add_argument("--no-server", action="store_true", help="Install and run self-checks without holding localhost:9914 open")
    args = ap.parse_args()
    return install_and_verify(Path(args.target_dir), run_server=not args.no_server)


if __name__ == "__main__":
    raise SystemExit(main())
